main.dashboard_body:
${jsonencode({
  widgets = [
    {
      type = "metric",
      x = 0, y = 0, width = 12, height = 6,
      properties = {
        metrics = [["AWS/ApplicationELB", "RequestCount", "LoadBalancer", aws_lb.main.arn_suffix]],
        period = 300, stat = "Sum", region = var.aws_region, title = "ALB Request Count"
      }
    },
    {
      type = "metric",
      x = 12, y = 0, width = 12, height = 6,
      properties = {
        metrics = [["AWS/EC2", "CPUUtilization", "AutoScalingGroupName", aws_autoscaling_group.app.name]],
        period = 300, stat = "Average", region = var.aws_region, title = "App Tier CPU"
      }
    },
    {
      type = "metric",
      x = 0, y = 6, width = 12, height = 6,
      properties = {
        metrics = [["AWS/RDS", "CPUUtilization", "DBInstanceIdentifier", aws_db_instance.main.id]],
        period = 300, stat = "Average", region = var.aws_region, title = "RDS CPU"
      }
    }
  ]
})}
